package com.shopwebsite.order;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
@Document("orders") public class Order { @Id private String id;private String userId,address,paymentMethod,status;private List<Item> items;private BigDecimal total;private Instant createdAt;public Order(){} public String getId(){return id;}public void setId(String v){id=v;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String v){paymentMethod=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public List<Item> getItems(){return items;}public void setItems(List<Item> v){items=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public record Item(String productId,String productName,BigDecimal price,int quantity,String emoji){} }
